mapper.select:
select date_format(create_time, '%Y-%m-%d') as date, count(id) as value
from user
where create_time >= #{begin}
  and create_time < #{end}
group by date_format(create_time, '%Y-%m-%d')
order by date

select oi.name as name, sum(oi.number) as value
from service_order_item oi
inner join service_order o on oi.order_id = o.id
where o.status in (5, 6)
  and o.pay_status = 1
  and o.order_time >= #{begin}
  and o.order_time < #{end}
group by oi.name
order by value desc
limit #{limit}

select count(id) from service_order
where status in (5, 6)

    and order_time >= #{begin}


    and order_time < #{end}

select sum(amount) from service_order
where pay_status = 1
  and status in (5, 6)

    and checkout_time >= #{begin}


    and checkout_time < #{end}
